import { validateQuestions } from "@/lib/validateQuestions";

export interface Question {
  id: number;
  question: string;
  answer: string;
  category?: string;
  keywords?: string[];
}

// Questions 1-349 were transcribed directly from the supplied PDF.
// To add an entry, append an object with a unique id. Keywords are optional;
// when omitted, relevant terms are derived locally from its question, answer, and category.
const ignoredKeywordWords = new Set(["a", "an", "and", "are", "as", "at", "based", "be", "because", "by", "can", "data", "does", "for", "from", "following", "has", "have", "in", "include", "indicates", "is", "it", "mainly", "of", "on", "or", "refers", "the", "this", "to", "used", "which", "with"]);

function createKeywords(question: string, answer: string, category: string): string[] {
  const terms = `${question} ${answer}`.toLowerCase().match(/[a-z][a-z0-9-]*/g) ?? [];
  const termsFromContent = terms.filter((term) => term.length > 2 && !ignoredKeywordWords.has(term));
  return Array.from(new Set([category.toLowerCase(), ...termsFromContent])).slice(0, 8);
}

